import json,numpy as np
from scipy.spatial.transform import Rotation
s=json.load(open('/app/output/spec.json'));P0=np.load('/app/output/initial_obs/proprio.npy')[0];P=np.load('/app/output/after_corrected_grasp_obs/proprio.npy')[-1];D=np.load('/app/output/after_corrected_grasp_obs/depth_wrist.npy')[-1]
def H(p):
 t=np.eye(4);t[:3,:3]=Rotation.from_quat(p[[20,21,22,19]]).as_matrix();t[:3,3]=p[16:19];return t
C=H(P)@np.linalg.inv(H(P0))@np.array(s['cameras']['wrist']['cam2world_gl']);print('cam origin',C[:3,3]);print('right',C[:3,0]);
for u,v in [(220,140),(220,130),(200,135),(170,135),(160,140),(160,155),(140,155)]:
 z=float(D[v,u]); X=np.array([(u-160)*z/386.274,-(v-160)*z/386.274,-z,1]);print((u,v),z,(C@X)[:3])
